'use strict';
const $=id=>document.getElementById(id);
const state={tab:'sms',sms:[],catalog:{providers:[],dids:[],extensions:[],sip_users:[],limit_profiles:[],ivrs:[],audio_endpoints:[],version:0},audit:[],info:{},telephony:null,media:[]};
const node=(tag,cls='',text='')=>{const item=document.createElement(tag);item.className=cls;if(text&&typeof text==='object'&&text.nodeType)item.append(text);else item.textContent=text;return item};
function notice(text){$('snackbar').textContent=text;$('snackbar').classList.add('visible');setTimeout(()=>$('snackbar').classList.remove('visible'),5000)}
async function api(path,method='GET',body){const response=await fetch(path,{method,cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!response.ok)throw Error((await response.text()).trim()||'Request failed');return response.status===204?null:response.json()}
const resourceCache=new Map();
async function linkedResources(kind,site,params={}){const query=new URLSearchParams({kind,site,...params}),key=query.toString();if(!resourceCache.has(key))resourceCache.set(key,api(`/api/routing/resources?${key}`).then(result=>result.resources||[]));return resourceCache.get(key)}
function optionList(select,resources,selected=[],placeholder='Select a resource'){select.replaceChildren();if(!select.multiple){const empty=node('option','',placeholder);empty.value='';empty.disabled=true;select.append(empty)}for(const resource of resources){const option=node('option','',`${resource.label||resource.id}${resource.meta?` · ${resource.meta}`:''}`);option.value=resource.id;option.selected=selected.includes(resource.id);select.append(option)}select.disabled=!resources.length}
function selectedValues(select){return [...select.selectedOptions].map(option=>option.value).filter(Boolean)}
async function load(){if(state.tab==='telephony'){await loadTelephony();return}try{[state.sms,state.catalog,state.audit,state.info]=await Promise.all([api('/api/providers'),api('/api/sip'),api('/api/audit'),api('/api/admin')]);state.catalog.sip_users ||= [];state.catalog.limit_profiles ||= [];state.catalog.ivrs ||= [];state.catalog.audio_endpoints ||= [];try{state.media=await api('/api/ivr/media')}catch{state.media=[]}render()}catch(error){notice(error.message)}}
async function loadTelephony(){ $('section-title').textContent='Telephony';$('admin-help').textContent='Live service replicas, active SIP registrations, calls and recent call detail records for this site.';$('add-record').hidden=true;$('search-label').hidden=true;const root=$('records');root.replaceChildren(node('p','muted','Loading telephony status…'));try{state.telephony=await api('/api/telephony');renderTelephony()}catch(error){root.replaceChildren(node('p','admin-error',error.message))} }
function telephonyTable(headers,rows){const table=document.createElement('table');table.className='cdr-table';const head=document.createElement('thead'),hr=document.createElement('tr');for(const title of headers)hr.append(node('th','',title));head.append(hr);table.append(head);const body=document.createElement('tbody');for(const values of rows){const tr=document.createElement('tr');for(const value of values)tr.append(node('td','',String(value??'')));body.append(tr)}table.append(body);return table}
function renderTelephony(){const root=$('records'),data=state.telephony||{};root.replaceChildren();const status=node('section','admin-card telephony-status');status.append(node('h3','','Systems'));for(const system of data.systems||[]){const row=node('div','status-row');row.append(node('strong','',system.name),node('span',`status-pill ${system.state==='connected'?'online':'offline'}`,system.state));status.append(row);if(system.detail)status.append(node('p','muted',system.detail))}status.append(node('p','muted',`Site ${data.site||'unknown'} · Checked ${data.checked_at?new Date(data.checked_at).toLocaleTimeString():''}`));const refresh=node('button','text-button','Refresh');refresh.type='button';refresh.onclick=loadTelephony;status.append(refresh);root.append(status);renderFreeSwitchDebug(root);
 const replicaSection=node('section','admin-card telephony-wide');replicaSection.append(node('h3','','Service replicas'));const replicas=data.replicas||[];if(!replicas.length)replicaSection.append(node('p','muted','No replica endpoints reported.'));else replicaSection.append(telephonyTable(['Service','Endpoint','State','Detail'],replicas.map(replica=>[replica.service,replica.target,replica.state,replica.detail||''])));root.append(replicaSection);
 const registrationSection=node('section','admin-card telephony-wide');registrationSection.append(node('h3','','Active SIP registrations and contacts'));for(const database of data.registrar_databases||[]){registrationSection.append(node('p','muted',`${database.name}: ${database.state}${database.detail?' · '+database.detail:''}`))}const registrations=data.registrations||[];if(!registrations.length)registrationSection.append(node('p','muted','No active contacts reported by the registrar databases.'));else registrationSection.append(telephonyTable(['Registrar','AoR','Contact','Received','Path','Connection / server','Instance / reg-id','Expires','User agent'],registrations.map(contact=>[`${contact.registrar}${contact.site?' · '+contact.site:''}`,`${contact.username}@${contact.domain}`,contact.contact,contact.received,contact.path,`${contact.connection_id||'—'} / ${contact.server_id||'—'}`,`${contact.instance||'—'} / ${contact.reg_id||'—'}`,new Date(contact.expires).toLocaleString(),contact.user_agent])));root.append(registrationSection);
 const live=node('section','admin-card telephony-wide');live.append(node('h3','','Active calls'));const calls=data.calls||[];if(!calls.length)live.append(node('p','muted',(data.systems||[]).some(item=>item.state==='connected')?'No active calls reported by connected interfaces.':'Live call interfaces are not connected.'));for(const call of calls){const card=node('article','call-card'),heading=node('div','call-heading');heading.append(node('strong','',`${call.caller||'Unknown caller'} → ${call.called||'Unknown destination'}`),node('span','status-pill online',call.state||'active'));card.append(heading,node('p','muted',`${call.system==='asterisk'?'Asterisk':'FreeSWITCH'} · ${call.name||call.id}`));if(call.started_at)card.append(node('p','muted',`Started ${new Date(call.started_at).toLocaleString()}`));const end=node('button','text-button danger','End call');end.type='button';end.onclick=()=>endCall(call);card.append(end);live.append(card)}root.append(live);const history=node('section','admin-card telephony-wide');history.append(node('h3','','Recent call records'));const records=data.cdr||[];if(!records.length)history.append(node('p','muted','No CDR records returned from connected databases.'));if(records.length)history.append(telephonyTable(['System','Started','From','To','Duration','Result'],records.map(record=>[record.system,new Date(record.started_at).toLocaleString(),record.caller,record.called,`${record.duration}s`,record.disposition])));root.append(history)}
async function endCall(call){if(!await confirmDelete(`End this ${call.system==='asterisk'?'Asterisk':'FreeSWITCH'} call from ${call.caller||'unknown'} to ${call.called||'unknown'}? This disconnects the active call.`))return;try{await api('/api/telephony/hangup','POST',{system:call.system,id:call.id});notice('Hangup requested.');await loadTelephony()}catch(error){notice(error.message)}}
async function loadTelephony(){if(!$('telephony-styles')){const link=document.createElement('link');link.id='telephony-styles';link.rel='stylesheet';link.href='/assets/telephony.css';document.head.append(link)}$('section-title').textContent='Telephony';$('admin-help').textContent='Live service topology, replica health, active SIP contacts, calls and recent call records for this site.';$('add-record').hidden=true;$('search-label').hidden=true;const root=$('records');root.replaceChildren(node('p','muted','Loading telephony topology…'));try{state.telephony=await api('/api/telephony');renderTelephony()}catch(error){root.replaceChildren(node('p','admin-error',error.message))}}
function ensureReplicaInspector(){
 let dialog=$('replica-inspector');
 if(dialog)return dialog;
 dialog=document.createElement('dialog');dialog.id='replica-inspector';dialog.className='replica-inspector';
 dialog.innerHTML='<form method="dialog"><header class="inspector-head"><div><p class="eyebrow">Replica inspector</p><h2 id="replica-title"></h2><p id="replica-subtitle" class="muted"></p></div><button class="icon-button" value="cancel" aria-label="Close replica inspector" title="Close">×</button></header><nav id="replica-tabs" class="inspector-tabs" aria-label="Replica details"><button type="button" data-panel="overview" aria-selected="true">Overview</button><button type="button" data-panel="calls">Active calls</button><button type="button" data-panel="connections">Connections</button><button type="button" data-panel="configuration">Configuration</button><button type="button" data-panel="diagnostics">Diagnostics</button></nav><section id="replica-panel" class="inspector-panel"></section></form>';
 document.body.append(dialog);return dialog;
}
function telephonyValue(value){return value===undefined||value===null||value===''?'—':String(value)}
function statusTone(state){return ['connected','ready','healthy','online'].includes(String(state).toLowerCase())?'healthy':['pending','degraded','connecting'].includes(String(state).toLowerCase())?'degraded':['unavailable','failed','error','offline'].includes(String(state).toLowerCase())?'failed':'unknown'}
function statusLabel(state){return state==='connected'?'Ready':state||'Unknown'}
function copyValue(value){navigator.clipboard?.writeText(String(value)).then(()=>notice('Copied to clipboard.')).catch(()=>notice('Copy is not available in this browser.'))}
function infoGrid(items){const grid=node('div','inspector-grid');for(const [label,value] of items){const cell=node('div','inspector-field');const dd=node('dd','',telephonyValue(value));if(value){const copy=node('button','text-button copy-button','Copy');copy.type='button';copy.title=`Copy ${label}`;copy.onclick=()=>copyValue(value);dd.append(copy)}cell.append(node('dt','',label),dd);grid.append(cell)}return grid}
function inspectorPanel(replica,panel,data){const panelRoot=$('replica-panel');panelRoot.replaceChildren();const calls=data.calls||[];
 if(panel==='overview'){panelRoot.append(node('div',`inspector-state ${statusTone(replica.state)}`,`${statusLabel(replica.state)} · ${replica.detail||'Control endpoint responding'}`),infoGrid([['Service',replica.service],['Endpoint',replica.target],['Workload',replica.workload],['Pod',replica.pod],['Namespace',replica.namespace],['Node',replica.node],['Pod IP',replica.pod_ip],['Site',replica.site||data.site],['Image',replica.image],['Restarts',replica.restarts],['Last refresh',data.checked_at?new Date(data.checked_at).toLocaleString():'']]),node('p','inspector-note','This view reports the live control data available to AVoIP Admin. Kubernetes-only metadata is shown when the backend provides it.'))}
 else if(panel==='calls'){panelRoot.append(node('p','inspector-note',calls.length?'Calls are reported by the connected control interfaces; replica ownership is not inferred unless the backend can prove it.':'No active calls reported by connected interfaces.'));if(calls.length)for(const call of calls){const card=node('article','inspector-call');card.append(node('strong','',`${call.caller||'Unknown'} → ${call.called||'Unknown'}`),node('span','status-pill online',call.state||'active'),node('p','muted',`${call.system==='asterisk'?'Asterisk':'FreeSWITCH'} · ${call.name||call.id}`));if(call.started_at)card.append(node('p','muted',`Started ${new Date(call.started_at).toLocaleString()}`));panelRoot.append(card)}}
 else if(panel==='connections'){const registrations=data.registrations||[];panelRoot.append(node('p','inspector-note',replica.service?.toLowerCase().includes('kamailio')?'Registrar contacts are shared state. A contact is not attributed to this replica without verified owner metadata.':'No service-specific connection inventory is exposed by the current control API.'));if(registrations.length)panelRoot.append(node('h3','','Active registrar contacts'),telephonyTable(['AoR','Contact','Transport / connection','Expires'],registrations.map(item=>[`${item.username}@${item.domain}`,item.contact,`${item.connection_id||'—'} / ${item.server_id||'—'}`,new Date(item.expires).toLocaleString()])))}
 else if(panel==='configuration'){panelRoot.append(node('div','empty-state','Effective configuration is intentionally not exposed by the current backend. No secrets, credentials or generated private configuration are sent to the browser.'),node('p','inspector-note','Add a redacted, service-specific configuration endpoint before enabling this view.'))}
 else {panelRoot.append(node('div','empty-state','No recent diagnostics are available for this replica.'),node('p','inspector-note','Use the existing workload and SIP observability tools for logs and traces. This interface does not provide arbitrary shell access.'))}
}
function openReplicaInspector(replica,data){const dialog=ensureReplicaInspector();$('replica-title').textContent=replica.pod||replica.target||replica.service;$('replica-subtitle').textContent=`${replica.service||'Service'} · ${statusLabel(replica.state)}`;const tabs=$('replica-tabs');for(const tab of tabs.querySelectorAll('button')){tab.onclick=()=>{for(const item of tabs.querySelectorAll('button'))item.setAttribute('aria-selected',item===tab?'true':'false');inspectorPanel(replica,tab.dataset.panel,data)}}inspectorPanel(replica,'overview',data);dialog.showModal()}
function serviceGroupName(replica){const service=String(replica.service||'Other');if(service.toLowerCase().startsWith('kamailio '))return `Kamailio — ${service.slice(9).replace(/-/g,' ')}`;if(service.toLowerCase().includes('kamailio'))return 'Kamailio — unknown role';if(service.toLowerCase().includes('freeswitch'))return 'FreeSWITCH';if(service.toLowerCase().includes('asterisk'))return 'Asterisk';if(service.toLowerCase().includes('rtpengine'))return 'RTPEngine';return service}
function replicaTile(replica,data){const button=node('button','replica-tile');button.type='button';button.setAttribute('aria-label',`Inspect ${replica.pod||replica.target||replica.service}`);button.onclick=()=>openReplicaInspector(replica,data);const tone=statusTone(replica.state);button.append(node('span',`health-dot ${tone}`,statusLabel(replica.state)),node('strong','replica-name',replica.pod||replica.target||replica.service),node('span','replica-service',replica.role?`Role: ${replica.role}`:replica.service||'Service'),node('span','replica-meta',`${replica.node||replica.pod_ip||'Endpoint details unavailable'}`));return button}
function renderTelephony(){const root=$('records'),data=state.telephony||{},replicas=data.replicas||[],registrations=data.registrations||[],calls=data.calls||[];root.replaceChildren();
 const healthy=replicas.filter(item=>statusTone(item.state)==='healthy').length,degraded=replicas.length-healthy;const summary=node('section','telephony-hero');summary.append(node('div','eyebrow','AVoIP platform'),node('h3','','Telephony topology'),node('p','muted',`Site ${data.site||'unknown'} · Last checked ${data.checked_at?new Date(data.checked_at).toLocaleTimeString():''}`));const metrics=node('div','telephony-metrics');for(const [label,value,tone] of [['Replica health',`${healthy} / ${replicas.length}`,degraded?'degraded':'healthy'],['Active contacts',registrations.length,'healthy'],['Active calls',calls.length,calls.length?'healthy':'unknown'],['Control systems',(data.systems||[]).filter(item=>item.state==='connected').length,'healthy']]){const metric=node('div','metric-card');metric.append(node('span','metric-label',label),node('strong',`metric-value ${tone}`,String(value)));metrics.append(metric)}summary.append(metrics);const refresh=node('button','text-button','Refresh topology');refresh.type='button';refresh.onclick=loadTelephony;summary.append(refresh);root.append(summary);
 const issues=(data.systems||[]).filter(item=>['degraded','unavailable'].includes(item.state));if(issues.length){const alert=node('section','telephony-system-alert');alert.setAttribute('role','status');alert.append(node('strong','','Some telephony data is unavailable'));for(const item of issues)alert.append(node('p','',`${item.name}: ${item.detail||item.state}`));root.append(alert)}renderFreeSwitchDebug(root);
 const topology=node('section','topology-area'),groups=new Map();for(const replica of replicas){const group=serviceGroupName(replica);if(!groups.has(group))groups.set(group,[]);groups.get(group).push(replica)}if(!replicas.length)topology.append(node('div','empty-state','No service replicas reported by the connected control interfaces.'));for(const [group,items] of groups){const card=node('article','service-card');const title=node('div','service-card-head');title.append(node('div','',node('h3','',group)),node('span',`status-pill ${items.every(item=>statusTone(item.state)==='healthy')?'online':'offline'}`,`${items.filter(item=>statusTone(item.state)==='healthy').length} / ${items.length} ready`));card.append(title,node('p','muted',`${items.length} discovered replica${items.length===1?'':'s'} · select a tile to inspect`));const tiles=node('div','replica-tiles');for(const replica of items)tiles.append(replicaTile(replica,data));card.append(tiles);topology.append(card)}root.append(topology);
 const sections=node('section','telephony-secondary');const tabs=node('div','telephony-subtabs');for(const [key,label] of [['registrations','Registrations'],['calls','Active calls'],['cdr','Recent calls / CDR']]){const tab=node('button',`telephony-subtab ${key==='registrations'?'active':''}`,label);tab.type='button';tab.onclick=()=>{for(const item of tabs.children)item.classList.remove('active');tab.classList.add('active');for(const item of sections.querySelectorAll('.telephony-panel'))item.hidden=item.dataset.panel!==key};tabs.append(tab)}sections.append(tabs);const registrationPanel=node('div','telephony-panel');registrationPanel.dataset.panel='registrations';registrationPanel.append(node('h3','','Active SIP contacts'));if(!registrations.length)registrationPanel.append(node('div','empty-state','No active contacts reported.'));else registrationPanel.append(telephonyTable(['Registrar','AoR','Contact','Path / connection','Expires','User agent'],registrations.map(item=>[`${item.registrar}${item.site?' · '+item.site:''}`,`${item.username}@${item.domain}`,item.contact,item.path||item.connection_id||'—',new Date(item.expires).toLocaleString(),item.user_agent||'—'])));sections.append(registrationPanel);const callsPanel=node('div','telephony-panel');callsPanel.dataset.panel='calls';callsPanel.hidden=true;callsPanel.append(node('h3','','Active calls'));if(!calls.length)callsPanel.append(node('div','empty-state','No active calls reported by connected interfaces.'));else callsPanel.append(telephonyTable(['System','From','To','State','Started'],calls.map(item=>[item.system,item.caller,item.called,item.state,new Date(item.started_at).toLocaleString()])));sections.append(callsPanel);const cdrPanel=node('div','telephony-panel');cdrPanel.dataset.panel='cdr';cdrPanel.hidden=true;cdrPanel.append(node('h3','','Recent call records'));const records=data.cdr||[];if(!records.length)cdrPanel.append(node('div','empty-state','No CDR records returned from connected databases.'));else cdrPanel.append(telephonyTable(['System','Started','From','To','Duration','Result'],records.map(item=>[item.system,new Date(item.started_at).toLocaleString(),item.caller,item.called,`${item.duration}s`,item.disposition])));sections.append(cdrPanel);root.append(sections);
}
