 if(tab==='extensions')$('admin-help').textContent='Link authorized providers, caller IDs and limit profiles from the current site catalog. External destinations remain explicit phone numbers because they are not internal resources.';
 if(tab==='dids')$('admin-help').textContent='Choose a managed destination resource when the route is internal. IVRs, extensions, Audio Endpoints, providers, caller IDs and limit profiles are loaded from the API only for the selected site/type; external numbers and SIPS URIs remain explicit inputs.';
 if(tab==='ivrs')$('admin-help').textContent='Build digit routes from linked AVoIP resources. The editor stores stable resource IDs and keeps unsupported legacy routes protected by server-side validation.';
 root.replaceChildren();
