 field('id','Internal ID');field('name','Display name');field('site','Site','select',['yvr','yxl']);field('greeting_asset','Greeting audio library asset','select',state.media.map(asset=>({value:asset.id,label:asset.name})));field('timeout_ms','Initial input timeout (milliseconds)','number');field('digit_timeout_ms','Inter-digit timeout (milliseconds)','number');field('max_digits','Maximum digits','number');field('invalid_retries','Invalid input retries','number');
 const kinds=[{value:'extension',label:'Extension'},{value:'audio_endpoint',label:'Audio endpoint'},{value:'ivr',label:'IVR'},{value:'media',label:'Audio library item'},{value:'did',label:'External number'},{value:'sip',label:'SIPS endpoint'},{value:'relayed',label:'Relayed extension'},{value:'relayed_did',label:'Relayed external number'}];
